const tentPh=new Float32Array(ANEM.length*NT);for(let i=0;i<tentPh.length;i++)tentPh[i]=rnd()*6.28;
tentGeo.setAttribute('aPhase',new THREE.InstancedBufferAttribute(tentPh,1));
