window.addEventListener('keydown',e=>{if(e.key==='Escape'){for(const id of['help','sofar','welcome','press','mapOv','card','liveGuide'])$(id).hidden=true;if(VR.on&&!VR.xr)exitVR();else if(TOUR.on)exitTour();}});
