  setTimeout(()=>{if(VR.on&&!VR.xr&&!VR.gyro)vrHint($t('这个页面读不到手机的陀螺仪（浏览器不支持，或者没有允许访问“动作与方向”），画面不会跟着手机转。<b>用手指左右上下拖动</b>来看四周，轻点屏幕开始或停止游动。'),10);},2200);
