    VR.rig.position.copy(camera.position);VR.rig.rotation.set(0,Math.atan2(-_vv.x,-_vv.z),0);
    scene.add(VR.rig);VR.rig.add(camera);camera.position.set(0,0,0);camera.quaternion.identity();
