  narrUnlock();
  TOUR.on=true;TOUR.paused=false;TOUR.prevSpeed=controls.autoRotateSpeed;controls.autoRotateSpeed=0.9;lastTouch=-1e9;
  document.body.classList.add('tour');$('tourBar').hidden=false;
